import 'dart:async'; import 'package:flutter_test/flutter_test.dart'; import 'package:eye_control/data/datasources/native_bridge.dart'; import 'package:eye_control/presentation/providers/tracking_provider.dart'; class FakeBridge extends NativeBridge{final StreamController<Map<String,dynamic>> c=StreamController.broadcast();@override Stream<Map<String,dynamic>> get screenPoints=>c.stream;Future<void> close() async { await c.close(); }} void main(){test('publishes latest screen point',()async{final b=FakeBridge();final p=TrackingProvider(bridge:b);p.start();b.c.add({'xPx':1,'yPx':2,'confidence':.8,'isBlinking':false,'timestampNs':7});await Future<void>.delayed(Duration.zero);expect(p.latest?.xPx,1);await p.stop();await b.close();});}